    pub fn submit(
        &self,
        journal: &FjallJournal,
        policy: RuntimePolicy,
    ) -> Result<AcceptedArtifact, super::ExecutorError> {
        self.catalog.submit_artifact(
            journal,
            &self.workflow,
            policy,
            std::slice::from_ref(&self.contract),
            std::slice::from_ref(&self.pack),
        )
    }

